<p class="eyebrow">Country Pack administration</p><h1>Countries</h1><div class="table-wrap"><table><thead><tr><th>Country Pack</th><th>Currency</th><th>Default locale</th><th>Availability</th><th></th></tr></thead><tbody><?php foreach($countries as $country): ?><tr><td><strong><?= e($country['name']) ?></strong><br><small><?= e($country['slug']) ?></small></td><td><?= e($country['currency_code'].' '.$country['currency_symbol']) ?></td><td><?= e($country['locale']) ?></td><td><span class="badge"><?= !empty($country['is_enabled'])?'Enabled':'Disabled' ?></span></td><td><a class="text-link" href="<?= e(route('admin.countries.show',['country'=>$country['id']])) ?>">Manage</a></td></tr><?php endforeach;?></tbody></table></div>
